import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/settings.md","filePath":"car-wash/settings.md"}'),a={name:"car-wash/settings.md"};function s(n,t,c,i,h,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Every Car Wash setting is edited in <code>/nay</code>, on the <strong>Car Wash</strong> page (scope <code>nay_car_wash.config</code>). Changes are saved in the database and applied to every player at once. <code>config.lua</code> only holds optional starting values, read on the very first start.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>Enabled</code></td><td>on / off</td><td>on</td><td>Turns every tunnel and pressure washer on or off.</td></tr><tr><td><code>InteractionMode</code></td><td><code>key</code> or <code>target</code></td><td><code>key</code></td><td>How players start a pressure washer: key prompt (E) or target eye. Tunnels always use E from the vehicle.</td></tr><tr><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> or <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Where the price is taken from. <code>cash_then_bank</code> uses the bank when cash is short.</td></tr><tr><td><code>JobDiscounts</code></td><td>list</td><td>none</td><td>Discounts for a job from a grade.</td></tr></tbody></table><p><code>JobDiscounts</code> entries:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Job</code></td><td>text, 1 to 32 characters</td><td>Job name, as in your framework.</td></tr><tr><td><code>MinGrade</code></td><td>number, 0 to 100</td><td>Lowest grade that gets the discount.</td></tr><tr><td><code>Percent</code></td><td>number, 1 to 100</td><td>Discount in percent. 100 makes it free.</td></tr></tbody></table><h2 id="tunnels" tabindex="-1">Tunnels <a class="header-anchor" href="#tunnels" aria-label="Permalink to &quot;Tunnels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>Programs</code></td><td>list, 1 to 8</td><td>Express $150, Standard $250, Premium $400</td><td>Wash programs offered in every tunnel.</td></tr><tr><td><code>Tunnels</code></td><td>list, up to 32</td><td>Strawberry, Little Seoul</td><td>The tunnels. Placed with the <a href="/car-wash/tunnels">tunnel editor</a>.</td></tr><tr><td><code>MaxVehicleWidth</code></td><td>meters, 1 to 6</td><td>2.25</td><td>Wider vehicles are refused.</td></tr><tr><td><code>BlockedClasses</code></td><td>list of vehicle classes</td><td>motorcycles, cycles, boats, helicopters, planes, trains</td><td>Vehicle classes refused at the entrance.</td></tr><tr><td><code>RequireDirt</code></td><td>on / off</td><td>off</td><td>Refuses vehicles that are already clean.</td></tr><tr><td><code>ReplaceMapIpls</code></td><td>on / off</td><td>on</td><td>At Strawberry, swaps the default car wash for its brushless version. Turn it off when a custom map or a mapping manager handles that car wash.</td></tr></tbody></table><p><code>Programs</code> entries:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Label</code></td><td>text, 1 to 32 characters</td><td>Name shown in the wash menu.</td></tr><tr><td><code>Price</code></td><td>number, 0 to 1000000</td><td>Price before discounts and the tunnel percentage.</td></tr><tr><td><code>SpeedPercent</code></td><td>number, 25 to 300</td><td>Speed relative to the tunnel speed.</td></tr><tr><td><code>Soap</code></td><td>on / off</td><td>Runs the soap arch.</td></tr><tr><td><code>Rinse</code></td><td>on / off</td><td>Runs the rinse arch.</td></tr><tr><td><code>Dry</code></td><td>on / off</td><td>Runs the dryer.</td></tr><tr><td><code>WaxMinutes</code></td><td>number, 0 to 1440</td><td>Minutes the vehicle stays clean after the wash. 0 means no wax.</td></tr></tbody></table><p><code>Tunnels</code> entries are easier to edit with the <a href="/car-wash/tunnels">tunnel editor</a>, which fills these fields for you:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Label</code></td><td>text, up to 48 characters</td><td>Name shown in the menu and on the blip. Optional.</td></tr><tr><td><code>Enabled</code></td><td>on / off</td><td>Closes one tunnel without deleting it.</td></tr><tr><td><code>Entry</code></td><td>position and heading</td><td>Where the driver stops and presses E.</td></tr><tr><td><code>Start</code></td><td>position</td><td>Start of the line the vehicle follows.</td></tr><tr><td><code>Finish</code></td><td>position</td><td>End of the line.</td></tr><tr><td><code>Width</code></td><td>meters, 2 to 10</td><td>Lane width: sizes the arches, limits the vehicle width (0.5 m margin) and is used by the blocked-lane check.</td></tr><tr><td><code>Speed</code></td><td>number, 0.5 to 8</td><td>Base speed through the tunnel, multiplied by the program <code>SpeedPercent</code>.</td></tr><tr><td><code>PricePercent</code></td><td>number, 0 to 1000</td><td>Percentage applied to every program price in this tunnel. 100 keeps the prices.</td></tr><tr><td><code>SoapJet</code></td><td>position</td><td>Soap arch.</td></tr><tr><td><code>HorizontalRoller</code></td><td>position</td><td>Top brush.</td></tr><tr><td><code>VerticalRoller</code></td><td>position</td><td>Side brushes.</td></tr><tr><td><code>RinseJet</code></td><td>position</td><td>Rinse arch.</td></tr><tr><td><code>Dryer</code></td><td>position</td><td>Steam dryer. Optional.</td></tr></tbody></table><p><code>BlockedClasses</code> entries have one field, <code>Class</code>, picked from the GTA vehicle classes by name.</p><h2 id="pressure-washers" tabindex="-1">Pressure washers <a class="header-anchor" href="#pressure-washers" aria-label="Permalink to &quot;Pressure washers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ManualEnabled</code></td><td>on / off</td><td>on</td><td>Turns the pressure washers on or off.</td></tr><tr><td><code>ManualModels</code></td><td>list, up to 16</td><td><code>prop_gas_airunit01</code></td><td>World props that become pressure washers, wherever the map has them.</td></tr><tr><td><code>ManualStations</code></td><td>list, up to 64</td><td>none</td><td>Pressure washers you place yourself.</td></tr><tr><td><code>ManualPricePerLevel</code></td><td>number, 0 to 100000</td><td>15</td><td>Price of one dirt level.</td></tr><tr><td><code>ManualSecondsPerLevel</code></td><td>seconds, 0.2 to 10</td><td>1</td><td>Time to clean one dirt level.</td></tr></tbody></table><p><code>ManualModels</code> entries have one field, <code>Model</code>: the prop model name (letters, digits and underscores).</p><p><code>ManualStations</code> entries:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Label</code></td><td>text, up to 48 characters</td><td>Name of the station. Optional.</td></tr><tr><td><code>Coords</code></td><td>position and heading</td><td>Where it stands. <strong>Use my position</strong> fills it from where you stand.</td></tr></tbody></table><p>More on the <a href="/car-wash/pressure-washers">Pressure washers</a> page.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ShowBlips</code></td><td>on / off</td><td>on</td><td>Shows the tunnels and pressure washer stations on the map.</td></tr><tr><td><code>BlipSprite</code></td><td>blip icon</td><td>100</td><td>Picked from a visual list of icons. Any number can still be typed for a custom blip.</td></tr><tr><td><code>BlipColor</code></td><td>blip colour</td><td>63</td><td>Picked from a visual list of colours.</td></tr><tr><td><code>BlipScale</code></td><td>0.2 to 2</td><td>0.8</td><td>Size of the blip.</td></tr></tbody></table>',21)])])}const b=e(a,[["render",s]]);export{u as __pageData,b as default};
